function download(name,content,type='application/json'){
 const blob=content instanceof Blob?content:new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);
 if(scenario&&/\.(?:html|docx|csv|json|sqlite)$/i.test(name))void documentLibrary.capture({filename:name,content:blob,mime:type,scenarioId:scenario.id,title:scenario.title,summary:documentSummary()}).then(result=>{if(result.ok&&page==='library')void documentLibrary.render();});
}
function documentSummary(){
 if(session){const x=Core.summarize(session,scenario);return `${x.pass?'검수 완료':'확인 필요'} · 충족 ${x.met} · 불일치 ${x.violated} · 확인 필요 ${x.unknown}`;}
 if(workerEnabled()&&workerFlow.started){const x=summarizeWorker(workerFlow.state),rows=x.rows||[];return `${x.completed?'검수 완료':'확인 필요'} · 충족 ${rows.filter(r=>r.verdict==='met').length} / ${rows.length}`;}
 return '회사 자료 구축 기록';
}
async function readDocumentLibrary(){if(!storage)throw new Error('브라우저 저장소를 사용할 수 없습니다. 다운로드한 파일을 보관해 주세요.');return new Promise((resolve,reject)=>{const q=storage.transaction('state').objectStore('state').get('documentLibrary');q.onsuccess=()=>resolve(q.result??null);q.onerror=()=>reject(q.error);});}
async function writeDocumentLibrary(value){if(!storage)throw new Error('브라우저 저장소를 사용할 수 없습니다. 다운로드한 파일을 보관해 주세요.');return new Promise((resolve,reject)=>{const t=storage.transaction('state','readwrite');t.objectStore('state').put(value,'documentLibrary');t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||new Error('문서 저장이 취소되었습니다.'));});}
function appendLibraryAccess(){if(page!=='report')return;const panel=document.createElement('section');panel.className='panel library-access';panel.innerHTML='<div><h2>저장한 문서 다시 보기</h2><p class="hint">이번 결과와 이전 실습에서 저장한 보고서·검수조서를 문서 보관함에서 확인하세요.</p></div><button class="secondary" id="open-document-library">문서 보관함으로</button>';main.append(panel);panel.querySelector('button').onclick=()=>navigate('library');}

async function openStorage(){return new Promise((resolve,reject)=>{const r=indexedDB.open('dynin-seminar-classroom-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function store(value){if(!storage)return;await new Promise((resolve,reject)=>{const t=storage.transaction('state','readwrite');t.objectStore('state').put(value,'current');t.oncomplete=resolve;t.onerror=()=>reject(t.error);});}
async function restore(){if(!storage)return null;return new Promise((resolve,reject)=>{const r=storage.transaction('state').objectStore('state').get('current');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function save(){try{await store({scenarioId:scenario?.id,bundle,session,page,pdfText,csvText,selectedMode,presentation:{measurementView,previewIndex},workerFlow:scenario?.id==='electronics_demo'?workerFlow.snapshot():null,companyBuild:scenario?.id==='electronics_demo'?companyBuilder.snapshot():null});$('#save-state').textContent=storage?'저장됨 · 이 브라우저':'저장 불가 · 파일 백업 필요';}catch(e){$('#save-state').textContent='저장 실패';toast('브라우저 저장에 실패했습니다. 진행 내보내기로 백업해 주세요.');}}
function navigate(next){if(documentOperation)return toast('자료 준비가 끝난 뒤 이동해 주세요.');if(!['home','library'].includes(next)&&!scenario)return toast('먼저 실습을 선택해 주세요.');if(['setup','run','review','report'].includes(next)&&!bundle)return toast('회사 자료에서 정보를 먼저 구축해 주세요.');if(['run','review','report'].includes(next)&&!session&&!workerFlow.started)return toast('작업 설정에서 작업을 시작해 주세요.');if(next==='run'){clearTimeout(toast.timer);$('#toast').style.display='none';}page=next;render();save();window.scrollTo(0,0);}
