function measurementPhotoFigure(key,label){
 const path=measurementPhotoPath(key);if(!path)return '';
 const product=key==='product',clip=`assets/measurement-operator-v2/scene-${key.toLowerCase()}`;
 const media=product?`<button type="button" class="measurement-photo-zoom" data-measurement-photo="${esc(path)}" aria-label="${esc(label)} 확대"><img src="${esc(path)}" alt="${esc(label)}"></button>`:`<video class="measurement-pov-video" controls playsinline muted preload="metadata" poster="${esc(path)}" aria-label="${esc(label)} 작업 영상"><source src="${esc(clip)}.webm" type="video/webm"><source src="${esc(clip)}.mp4" type="video/mp4"></video>`;
 return `<figure class="measurement-generated-photo" data-photo-kind="${esc(key)}">${media}<figcaption><span>${esc(label)}</span><small>${product?'제품번호 BSH-2630 · 플랜지 부시':'계측 작업 영상'}</small></figcaption></figure>`;
}
