function measurementScenePresentation(cp,head,feature){
 const original=`<img id="scene-image" class="measure-illustration" src="${esc(cp.image)}" alt="${esc(cp.label)}">`;
 const reading=`<div class="reading-card"><span>장면의 최초 표시 · 강의용 예시</span><strong>${esc(head.raw||head.value||'—')}</strong><p>${esc(cp.note||'')}</p></div>`;
 return measurementPhotoPath(feature.code)?measurementPhotoFigure(feature.code,`${feature.code} ${featureName(feature)} 측정 장면`)+`<div class="measurement-reference-row"><div class="measurement-reading-reference"><span>입력용 수치 도해 · 클릭 확대</span>${original}</div>${reading}</div><p class="hint measurement-photo-note">판정은 직접 입력한 값과 검사 기준으로 계산합니다. 생성 사진에서 숫자를 판독하는 실습은 아닙니다.</p>`:original+reading;
}

