function featureFor(id){return inspectionInfo().features.find(f=>f.criterionId===id);}
function featureName(f){return String(f.label).replace(/^[ABC]\s*[·:.-]\s*/,'');}
function productChoice(){return `<section class="panel product-selector"><div class="section-row" style="margin:0 0 14px"><h2>01 · 검사할 제품을 선택하세요</h2><span class="tag">강의용 제품 2종</span></div><div class="product-options">${[{id:measurementInputs()?'measurement_input_demo':'measurement_demo',name:'표준형 플랜지 부시',code:'BSH-2630',description:'먼저 시작하기 · 기본 허용 범위'},{id:measurementInputs()?'measurement_input_precision_demo':'measurement_precision_demo',name:'정밀형 플랜지 부시',code:'BSH-2630-P',description:'비교 실습 · 더 좁은 길이 허용 범위'}].map(p=>`<button class="product-option ${scenario.id===p.id?'selected':''}" data-product-scenario="${p.id}" ${scenario.id===p.id?'aria-pressed="true"':'aria-pressed="false"'}><span>${esc(p.code)}</span><strong>${esc(p.name)}</strong><small>${esc(p.description)}</small></button>`).join('')}</div><p class="hint">제품을 바꾸면 해당 제품의 도면·검사 기준을 새로 불러옵니다. 측정 기록은 제품별로 따로 시작합니다.</p></section>`;}
function inspectionIdentity(){const i=inspectionInfo();return `<div class="measurement-identity"><div><small>선택한 제품</small><strong>${esc(i.productName)} <span>${esc(i.productId)}</span></strong></div><div><small>적용 도면</small><strong>${esc(i.drawingId)} · Rev.${esc(i.drawingRevision)}</strong></div><div><small>검사 대상</small><strong>${esc(i.specimenId)}</strong></div>${session?.inspectionDetails?`<div><small>검사자 / LOT</small><strong>${esc(session.inspectionDetails.inspector)}</strong><span>${esc(session.inspectionDetails.lot)}</span></div>`:''}</div>`;}
function measurementPending(id){return Boolean(session?.questions.some(q=>q.criterionId===id&&!['resolved','superseded'].includes(q.state)));}
function featureStatus(id){return measurementPending(id)?'unknown':session?getSummary().rows.find(r=>r.criterionId===id)?.verdict:'not_due';}
function drawingPanel(activeId=null,showValues=false){const i=inspectionInfo();return engineeringDrawing({inspection:i,assessments:showValues?session?.assessments||{}:{},statuses:Object.fromEntries(i.features.map(f=>[f.criterionId,showValues?featureStatus(f.criterionId):'not_due'])),criteria:(session?.bundle||bundle)?.criteria||[],activeId,inspector:session?.inspectionDetails?.inspector||'',lot:session?.inspectionDetails?.lot||'',showValues});}
function enhanceMeasurementDocuments(){
  main.querySelector('.page-heading h1').textContent='제품을 고르면 도면과 기준이 준비됩니다';
  main.querySelector('.page-heading p').textContent='제품 선택 → 도면의 A·B·C 위치 확인 → 검사 기준 불러오기 순서로 준비해 보세요.';
  const before=main.querySelector('.gridwide');before.insertAdjacentHTML('beforebegin',productChoice()+`<section class="panel drawing-overview"><div class="section-row" style="margin-top:0"><h2>02 · 제품 도면과 검사 위치</h2><span class="tag">강의용 도면</span></div>${inspectionIdentity()}${measurementPhotoPath('product')?`<div class="measurement-product-presentation">${measurementPhotoFigure('product','플랜지 부시 제품')}<div>${drawingPanel()}</div></div>`:drawingPanel()}<p class="hint">A는 플랜지 외경, B는 전체 길이, C는 플랜지 두께입니다. 단위는 모두 mm입니다.</p></section>`);
  $('#compile').textContent='검사 기준 불러오기 · 정보 구축';
  if($('#next-setup'))$('#next-setup').textContent='검사 시작 준비';
  main.querySelectorAll('[data-product-scenario]').forEach(b=>b.onclick=()=>safe(()=>selectScenario(b.dataset.productScenario)));bindMeasurementPhotos();
}
function measurementSetupView(){
 const i=inspectionInfo();main.innerHTML=heading('STEP 02 · 검사 시작','제품과 측정 위치를 확인하세요','불러온 도면과 검사 대상이 맞으면 측정 기록을 시작합니다.')+inspectionIdentity()+`<div class="gridwide"><section class="panel"><h2>이번 검사의 도면</h2>${drawingPanel()}<p class="hint">도면번호와 개정은 이 실습 기록에 고정됩니다.</p></section><section class="panel"><div class="work-order"><span>검사 지시</span><strong>${esc(scenario.orderId)}</strong><p>${esc(i.productName)} · 검사 수량 1개</p></div><h2>세 위치를 차례로 확인합니다</h2>${i.features.map(f=>`<div class="measurement-task"><span class="feature-code">${esc(f.code)}</span><div><strong>${esc(featureName(f))}</strong><small>${esc(f.instrument)}</small></div></div>`).join('')}${measurementInputs()?`<div class="field-row"><label class="field">검사자 이름<input id="inspection-inspector" maxlength="80" value="${esc(session?.inspectionDetails?.inspector||'김민수')}" ${session?'readonly':''}></label><label class="field">검사 LOT<input id="inspection-lot" maxlength="64" value="${esc(session?.inspectionDetails?.lot||'LOT-001')}" ${session?'readonly':''}></label></div><div class="lesson-tip"><strong>측정 기록</strong><p>A 외경과 B 길이의 숫자를 직접 기록합니다. C 두께의 가려진 숫자는 Agent 질문을 통해 확인합니다. 이름과 LOT도 검수조서에 함께 남습니다.</p></div>`:`<div class="lesson-tip"><strong>확인 항목</strong><p>마지막 두께 값의 한 자리가 불확실합니다. 값을 직접 확인해 기록하고, 같은 값도 검사 기준이 바뀌면 결과가 달라지는지 살펴보세요.</p></div>`}<div class="actions"><button id="start-session" class="primary">${session?'현재 검사 계속':'측정 기록 시작'}</button><button id="change-product" class="quiet">제품 다시 선택</button></div><p class="hint">측정값과 확인 이력은 이 작업 기록에 함께 저장됩니다.</p></section></div>`;
 $('#start-session').onclick=()=>safe(async()=>{if(!session){let next=Core.createSession(scenario,bundle);if(measurementInputs())next=Core.setInspectionDetails(next,{inspector:$('#inspection-inspector').value,lot:$('#inspection-lot').value});session=next;}await syncDb();await save();navigate('run');});$('#change-product').onclick=()=>navigate('documents');
}
function measurementTable(){return `<div class="table-scroll"><table class="measurement-table"><thead><tr><th>검사 위치</th><th>허용 범위</th><th>기록값</th><th>판정</th><th>기록 출처</th></tr></thead><tbody>${rows().map(({c,a,status})=>{const f=featureFor(c.id);return `<tr data-criterion="${esc(c.id)}"><td><strong>${esc(f.code)} · ${esc(featureName(f))}</strong><small>${esc(f.instrument)}</small></td><td>${esc(c.lower)}–${esc(c.upper)} ${esc(c.unit)}${String(c.lower)!==String(f.lower)||String(c.upper)!==String(f.upper)?`<small>변경된 실습 기준<br>도면 ${esc(f.lower)}–${esc(f.upper)} ${esc(f.unit)}</small>`:'<small>도면 기준</small>'}</td><td class="recorded-value">${a?.measurement?.valid?`${esc(a.measurement.value)} <small class="measure-unit">${esc(a.measurement.unit)}</small>`:a?'확인 필요':'—'}${a?`<small>최초 후보: ${esc(a.measurement?.raw||a.rawProposal?.raw||'—')}</small>`:''}</td><td>${badge(status)}</td><td>${a?esc(originLabel[a.origin]||a.origin):'기록 전'}${a?.workerConfirmation?`<small>확인값 ${esc(a.workerConfirmation.value)} ${esc(a.workerConfirmation.unit)}</small>`:''}</td></tr>`;}).join('')}</tbody></table></div>`;}
function measurementRunView(){
 if(measurementInputs())return measurementInputRunView();
 const cp=currentCheckpoint(),head=cp.assessments[0],feature=featureFor(head.criterionId),a=session.assessments[head.criterionId],summary=getSummary(),done=session.position===scenario.checkpoints.length-1;
 main.innerHTML=heading('STEP 03 · 계측 기록','측정값을 도면 위치에 기록해요','측정 장면의 값을 확인하고 기록하세요. 불확실한 값은 질문으로 확인합니다.',`<button id="to-review" class="secondary">전체 검사 결과</button>`)+inspectionIdentity()+`<div class="measurement-workspace"><section class="panel measurement-drawing"><div class="section-row" style="margin-top:0"><h2>도면과 측정 결과</h2><span class="tag">현재 위치 ${esc(feature.code)}</span></div>${drawingPanel(feature.criterionId,true)}<p class="hint">기록값은 연결된 A·B·C 위치에 표시됩니다. 임의 영상에서 위치를 인식한 결과는 아닙니다.</p></section><div class="stack"><section class="panel measurement-scene"><div class="section-row" style="margin-top:0"><h2>${esc(feature.code)} · ${esc(featureName(feature))}</h2><span class="tag">${esc(feature.instrument)}</span></div><img id="scene-image" class="measure-illustration" src="${esc(cp.image)}" alt="${esc(cp.label)}"><div class="reading-card"><span>${a?.measurement?.valid?'기록된 측정값':a?'확인이 필요한 후보':'기록할 판독 후보'}</span><strong id="reading-value">${a?.measurement?.valid?esc(a.measurement.value)+' <small>'+esc(a.measurement.unit)+'</small>':esc(head.raw||'—')}</strong><p>${esc(cp.note||head.reason||'')}</p></div><div class="checkpoint-list measurement-checkpoints">${scenario.checkpoints.map((x,n)=>`<button data-preview="${n}" class="${n===previewIndex?'selected ':''}${n<=session.position?'done':''}">${esc(inspectionInfo().features[n].code)} · ${esc(featureName(inspectionInfo().features[n]))}</button>`).join('')}</div><div class="actions"><button id="advance" class="primary" ${done?'disabled':''}>${session.position<0?'A 측정값 기록':done?'세 위치 기록 완료':`${inspectionInfo().features[session.position+1].code} 측정값 기록`}</button><span class="hint">${session.position+1} / 3개 위치 기록</span></div></section><section class="panel question-panel"><h2>불확실한 값 확인하기</h2><div id="questions"></div></section>${done?`<section class="completion-card ${summary.pass?'success':''}"><h2>${summary.pass?'세 위치의 검사가 완료되었습니다':summary.violated?'허용 범위를 벗어난 값이 있습니다':'확인할 값이 남아 있습니다'}</h2><p>측정값과 확인 답변을 검수조서로 남겨 보세요.</p><button id="measurement-finish" class="primary">검수조서 만들기</button></section>`:''}</div></div><section class="panel" style="margin-top:22px"><h2>측정 기록표</h2>${measurementTable()}</section>`;
 main.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{previewIndex=Number(b.dataset.preview);render();});
 $('#scene-image').onclick=()=>{const d=$('#image-modal');d.querySelector('img').src=cp.image;d.showModal();};
 $('#advance').onclick=()=>safe(async()=>{session=Core.advance(session,scenario);previewIndex=session.position;bundle=session.bundle;await syncDb();await save();render();if(session.questions.some(q=>q.state==='created'))toast('두께 값이 불확실합니다. 표시를 다시 확인하고 값과 단위를 입력하세요.');});
 $('#to-review').onclick=()=>navigate('review');if($('#measurement-finish'))$('#measurement-finish').onclick=()=>navigate('review');measurementQuestions();
}
function measurementInputRunView(){
 const cp=currentCheckpoint(),index=scenario.checkpoints.indexOf(cp),head=cp.assessments[0],feature=featureFor(head.criterionId),a=session.assessments[head.criterionId],summary=getSummary(),isManual=index<2,observed=index<=session.position;
 const nextIndex=Math.min(session.position+1,scenario.checkpoints.length-1),done=session.position===scenario.checkpoints.length-1;
 document.body.classList.toggle('operator-active',measurementView==='operator');
 main.innerHTML=measurementWorkplace({view:measurementView,inspection:inspectionInfo(),details:session.inspectionDetails,feature,index,assessment:a,status:featureStatus(feature.criterionId),observed,done,summary,checkpoint:cp,head,progress:session.position+1,nextIndex,drawing:drawingPanel(feature.criterionId,true),table:measurementTable(),checkpoints:scenario.checkpoints});
 const setView=view=>{measurementView=view;render();save();window.scrollTo(0,0);};
 $('#measurement-view-switch').onclick=()=>setView(measurementView==='operator'?'monitor':'operator');
 if($('#measurement-show-monitor'))$('#measurement-show-monitor').onclick=()=>setView('monitor');
 if($('#measurement-return-worker'))$('#measurement-return-worker').onclick=()=>setView('operator');
 main.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{previewIndex=Number(b.dataset.preview);render();save();});
 if($('#scene-image'))$('#scene-image').onclick=()=>{const d=$('#image-modal');d.querySelector('img').src=cp.image;d.showModal();};
 if($('#measurement-entry'))$('#measurement-entry').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));safe(async()=>{
  let next=session;if(index>next.position)next=Core.advance(next,scenario,index);
  next=Core.requestMeasurementConfirmation(next,feature.criterionId);
  const q=next.questions.find(q=>q.criterionId===feature.criterionId&&!['resolved','superseded'].includes(q.state));
  next=Core.markDelivered(next,q.id,'screen');next=Core.answerQuestion(next,q.id,{...data,target:cp.target,text:`${feature.code} 측정 장면을 보고 직접 입력했습니다.`});
  session=next;bundle=session.bundle;await syncDb();await save();render();
 });};
 if($('#advance'))$('#advance').onclick=()=>safe(async()=>{session=Core.advance(session,scenario,index);bundle=session.bundle;await syncDb();await save();render();});
 if($('#measurement-next-scene'))$('#measurement-next-scene').onclick=()=>{previewIndex=nextIndex;setView('operator');};
 $('#to-review').onclick=()=>navigate('review');if($('#measurement-finish'))$('#measurement-finish').onclick=()=>navigate('review');if($('#questions'))measurementQuestions();
 const video=$('#measurement-camera');if(video&&measurementView==='operator')void video.play().catch(()=>{});
}

function measurementQuestions(){
 const active=session.questions.filter(q=>!['resolved','superseded'].includes(q.state));
 $('#questions').innerHTML=active.length?active.map(q=>{const f=featureFor(q.criterionId),rule=session.bundle.criteria.find(c=>c.id===q.criterionId);return `<div class="question" data-q="${esc(q.id)}"><span class="tag">${esc(f.code)} · ${esc(featureName(f))}</span><p>${esc(session.assessments[q.criterionId]?.proposedQuestion||'표시된 값을 다시 확인하고 측정값과 단위를 알려 주세요.')}</p><small>검사 대상 ${esc(q.target)}</small><div class="actions"><button class="secondary deliver" data-id="${esc(q.id)}">질문 확인</button><button class="quiet speak" data-id="${esc(q.id)}">질문 듣기</button></div><form class="answer-form" data-id="${esc(q.id)}"><input type="hidden" name="target" value="${esc(q.target)}"><div class="field-row"><label class="field">확인한 값<input name="value" inputmode="decimal" placeholder="직접 확인한 값" required></label><label class="field">단위<input name="unit" value="${esc(rule.unit)}" required></label></div><label class="field">확인 메모<textarea name="text" rows="2" placeholder="예: 표시를 가까이에서 다시 확인했습니다."></textarea></label><div class="actions"><button class="primary" type="submit" ${q.state==='created'?'disabled':''}>확인값 기록</button><button type="button" class="quiet fill-measurement" ${q.state==='created'?'disabled':''}>예시값 5.78 mm 넣기</button></div><p class="hint">예시값은 버튼을 눌러 입력한 후 기록합니다. 다른 값을 넣으면 해당 값 그대로 판정합니다.</p></form></div>`;}).join(''):`<div class="empty">${session.questions.length?'확인한 값이 측정표에 기록되었습니다.<br>검사 결과에서 답변을 다시 확인할 수 있습니다.':'불확실한 값이 나오면 여기에서 확인합니다.<br>다음 위치의 측정값을 기록하세요.'}</div>`;
 $('#questions').querySelectorAll('.deliver').forEach(b=>b.onclick=()=>safe(async()=>{session=Core.markDelivered(session,b.dataset.id,'screen');await syncDb();await save();render();}));
 $('#questions').querySelectorAll('.speak').forEach(b=>b.onclick=()=>{if(!('speechSynthesis'in window))return toast('질문 확인 버튼으로 진행해 주세요.');const q=session.questions.find(q=>q.id===b.dataset.id),u=new SpeechSynthesisUtterance(session.assessments[q.criterionId]?.proposedQuestion||q.text);u.lang='ko-KR';u.onend=()=>safe(async()=>{session=Core.markDelivered(session,q.id,'audio');await syncDb();await save();render();});u.onerror=()=>toast('음성 재생을 지원하지 않습니다. 질문 확인 버튼을 이용하세요.');speechSynthesis.cancel();speechSynthesis.speak(u);});
 $('#questions').querySelectorAll('.fill-measurement').forEach(b=>b.onclick=()=>{const f=b.closest('form');f.elements.value.value='5.78';f.elements.unit.value='mm';f.elements.text.value='계측기 표시를 다시 확인했습니다.';f.elements.value.focus();});
 $('#questions').querySelectorAll('form').forEach(f=>f.onsubmit=e=>{e.preventDefault();safe(async()=>{session=Core.answerQuestion(session,f.dataset.id,Object.fromEntries(new FormData(f)));await syncDb();await save();render();toast('확인값을 기록하고 허용 범위와 비교했습니다.');});});
}
function measurementReviewView(){
 const summary=getSummary();main.innerHTML=heading('STEP 04 · 검사 결과','측정 결과와 확인값을 검토하세요','도면 위치별 측정 결과와 작업자 확인 이력을 검토합니다.')+inspectionIdentity()+stats()+`<section class="panel"><h2>현재 검사 결과</h2>${measurementTable()}<div class="notice ${summary.pass?'success':'warning'}">${summary.pass?'세 위치가 현재 검사 기준을 충족했습니다.':summary.violated?'범위를 벗어난 값이 있습니다. 원래 값과 확인 이력을 그대로 보존합니다.':'불확실하거나 아직 기록하지 않은 값이 있습니다.'}</div><div class="actions"><button id="go-report" class="primary">검수조서 만들기</button><button id="back-run" class="secondary">측정 / 질문으로</button><button id="change-product" class="quiet">다른 제품 선택</button></div></section><div class="grid2" style="margin-top:22px"><section class="panel"><h2>${measurementInputs()?'선택 · 허용 범위 비교':'허용 범위를 바꾸어 비교'}</h2><p class="hint">예: A 외경의 상한을 26.25 mm로 바꾸어 보세요. 26.30이라는 기록값은 그대로 남고 판정만 달라집니다.</p>${session.bundle.criteria.map(c=>{const f=featureFor(c.id);return `<form class="range-form" data-id="${esc(c.id)}"><strong>${esc(f.code)} · ${esc(featureName(f))}</strong><span class="original-limit">도면 기준: ${esc(f.lower)}–${esc(f.upper)} ${esc(f.unit)} · 원본 도면은 유지됩니다.</span><div class="field-row"><label class="field">실습 하한 (${esc(c.unit)})<input name="lower" value="${esc(c.lower)}" required></label><label class="field">실습 상한 (${esc(c.unit)})<input name="upper" value="${esc(c.upper)}" required></label><button class="secondary" type="submit">새 기준 적용</button></div></form>`;}).join('')}</section><section class="panel"><h2>작업자 확인 기록</h2>${session.questions.length?session.questions.map(q=>`<div class="answer-history"><strong>${esc(featureFor(q.criterionId).code)} · ${esc(featureName(featureFor(q.criterionId)))}</strong><p>${q.answers.length?q.answers.map(a=>`${esc(a.value)} ${esc(a.unit)} · ${esc(a.text||'확인값 입력')}`).join('<br>'):'아직 답변 없음'}</p></div>`).join(''):'<p class="hint">아직 확인 질문이 없습니다.</p>'}${session.bundle.criteria.filter(c=>session.assessments[c.id]?.measurement?.workerConfirmed).map(c=>`<button class="quiet reopen-answer" data-id="${esc(c.id)}">${esc(featureFor(c.id).code)} 확인값 다시 입력</button>`).join('')}<p class="hint">값을 다시 확인해도 이전 답변과 최초 판독 후보는 이력에 남습니다.</p><details><summary>상세 기록 보기</summary><pre>${esc(JSON.stringify(session.events,null,2))}</pre></details></section></div>`;
 $('#go-report').onclick=()=>navigate('report');$('#back-run').onclick=()=>navigate('run');$('#change-product').onclick=()=>navigate('documents');
 main.querySelectorAll('.range-form').forEach(f=>f.onsubmit=e=>{e.preventDefault();safe(async()=>{const v=Object.fromEntries(new FormData(f));session=Core.setRange(session,f.dataset.id,v.lower,v.upper);bundle=session.bundle;await syncDb();await save();render();toast('기록값을 유지하고 새 허용 범위로 판정했습니다.');});});
 main.querySelectorAll('.reopen-answer').forEach(b=>b.onclick=()=>safe(async()=>{session=Core.reopenQuestion(session,b.dataset.id);if(measurement())previewIndex=inspectionInfo().features.findIndex(f=>f.criterionId===b.dataset.id);if(mechanical())mechanicalFlow.focusCriterion(b.dataset.id);await syncDb();await save();navigate('run');}));
}

function currentCheckpoint(){return scenario.checkpoints[Math.max(0,Math.min(previewIndex,scenario.checkpoints.length-1))];}
function getSummary(){return Core.summarize(session,scenario);}
function rows(){return getSummary().rows.map(r=>({c:session.bundle.criteria.find(c=>c.id===r.criterionId),a:session.assessments[r.criterionId],status:measurement()&&measurementPending(r.criterionId)?'unknown':r.verdict}));}
function stats(){const r=rows();return `<div class="metric-grid">${[['met','충족'],['violated','불일치'],['unknown','확인 필요'],['rest','미검토 / 미도래']].map(([k,l])=>`<div class="metric"><span>${l}</span><strong>${r.filter(x=>k==='rest'?['not_due','unassessed'].includes(x.status):x.status===k).length}</strong></div>`).join('')}</div>`;}
function policyOf(c){return c.allowWorker?'worker_attestation':'visual_only';}
function assessmentTable(){if(measurement())return measurementTable();return `<div class="table-scroll"><table><thead><tr><th>검사 항목</th><th>현재 판정 / 기준</th><th>관찰·답변과 근거</th></tr></thead><tbody>${rows().map(({c,a,status})=>`<tr data-criterion="${esc(c.id)}"><td>${esc(c.label)}<small>${esc(c.target)}</small></td><td>${c.kind==='range'?`${esc(c.lower)}–${esc(c.upper)} ${esc(c.unit)}<br>`:''}${badge(status)}${policyEnabled()&&c.kind==='visual'?`<small>${policyOf(c)==='worker_attestation'?'작업자 확인 허용':'시각 증거만 인정'}</small>`:''}</td><td>${a?.measurement?.valid?`${esc(a.measurement.value)} ${esc(a.measurement.unit||'')}<br>`:''}${recorded()&&a?.rawProposal?`<div class="model-observation">모델 관찰: ${esc({present:'조건이 보임',absent:'반대 근거가 보임',unclear:'불명확'}[a.rawProposal.observation]||a.rawProposal.observation)}<br><small>${esc(a.rawProposal.reason||'')}</small></div>`:''}${demo()&&a?.rawExampleVerdict?`<div class="model-observation">예시 관찰: ${esc(statusLabel[a.rawExampleVerdict]||a.rawExampleVerdict)}</div>`:''}${a?.workerConfirmation?`<div class="worker-observation">작업자 답변: ${esc(statusLabel[a.workerConfirmation.confirmation]||'확인 필요')}<br><small>${esc(a.workerConfirmation.text)}</small></div>`:''}${esc(a?.reason||'아직 이 항목의 증거가 기록되지 않았습니다.')}<small>${a?.image?`<a href="${esc(a.image)}" target="_blank" rel="noopener">${a.evidenceKind==='context_only'?'참고 장면 · 모델 인용 없음':'인용 증거 사진'} · 원본 ${fmt(a.sourceTime??a.time)}</a><br>`:''}${a?esc(originLabel[a.origin]||a.origin||'교육용 작성 관찰'):''}${a?.receipt?.id?` · 응답 ${esc(a.receipt.id)}`:''}</small></td></tr>`).join('')}</tbody></table></div>`;}
function modelInspector(cp){
  if(!recorded())return `<details class="instructor-tools"><summary>${demo()?'강사용 · 이 장면의 예시 구성 보기':'이번 관찰 입력과 교육 이벤트 보기'}</summary><pre>${esc(JSON.stringify(cp,null,2))}</pre></details>`;
  if(previewIndex>session.position)return '<div class="notice">이 장면의 실제 모델 응답은 해당 관찰을 실행하면 공개됩니다. 미리보기는 검사 기록에 반영되지 않습니다.</div>';
  const entry=recordingPack.entries.find(e=>e.checkpointId===cp.id),assets=recordingAssets.get(cp.id);
  if(!entry||!assets)return '<div class="notice warning">검증된 모델 입력·출력 기록을 찾지 못했습니다.</div>';
  const requestDisplay=structuredClone(assets.request);
  for(const message of requestDisplay.messages||[])for(const part of Array.isArray(message.content)?message.content:[])if(part.type==='image_url')part.image_url={...part.image_url,url:'[아래 개별 이미지 참조 · 전체 요청 JSON에는 실제 이미지 데이터 포함]'};
  return `<details id="model-inspector" class="recording-inspector"><summary>실제 모델 입력·출력 확인 · ${esc(entry.receipt.id)}</summary><div class="notice"><strong>${esc(entry.receipt.model)}</strong><br>이 응답은 수집 시 실행한 모델의 저장 결과입니다. 현재 답변이나 정책 변경으로 모델이 다시 실행되지는 않습니다.</div><h3>모델에 전달한 이미지 ${entry.inputImages.length}장</h3><div class="input-image-grid">${entry.inputImages.map(i=>`<figure><a href="${esc(i.path)}" target="_blank" rel="noopener"><img src="${esc(i.path)}" loading="lazy" alt="모델 입력 ${esc(i.id)}"></a><figcaption>${esc(i.id)} · ${fmt(i.time)}<br>${esc(i.role||'관찰 이미지')}</figcaption></figure>`).join('')}</div><h3>실제 요청의 프롬프트·설정</h3><p class="hint">아래 표시에서 이미지 데이터 문자열만 생략했습니다. 전체 요청 JSON에는 전송한 이미지 데이터도 포함되어 있습니다.</p><pre>${esc(JSON.stringify(requestDisplay,null,2))}</pre><div class="actions"><a class="button secondary" href="${esc(entry.receipt.requestPath)}" download>전체 실제 요청 JSON</a><a class="button secondary" href="${esc(entry.receipt.responsePath)}" download>원시 응답 JSON</a></div><h3>원시 모델 응답</h3><pre id="raw-model-response">${esc(JSON.stringify(assets.response,null,2))}</pre>${entry.failure?`<div class="notice warning">수집 실패 보존: ${esc(entry.failure.kind)} · ${esc(entry.failure.message)}</div>`:''}<h3>검증된 파일 식별값</h3><pre>request SHA-256: ${esc(entry.receipt.requestSha256)}
response SHA-256: ${esc(entry.receipt.responseSha256)}</pre></details>`;
}
function runView(){
  if(measurement())return measurementRunView();
  if(demo())return demoRunView();
  const cp=currentCheckpoint();const observed=scenario.checkpoints[session.position]?.recording?.output;
  main.innerHTML=heading('STEP 03 · OBSERVE & CHECK',esc(scenario.title),'관찰 구간을 하나씩 진행하고, 질문과 결과를 확인하세요. 영상 탐색은 기록을 변경하지 않습니다.',`<button id="to-review" class="secondary">결과 검토</button>`)+stats()+`<div class="gridwide"><section class="panel"><div class="section-row" style="margin-top:0"><h2>장면과 증거</h2><span class="tag">${scenario.timelineKind==='lesson_case_order_not_continuous_video'?`독립 사례 ${previewIndex+1} · 원본 ${fmt(cp.sourceTime||0)}`:fmt(cp.time)} · 원본 자료</span></div><div class="media-stage"><img id="scene-image" src="${esc(cp.image)}" alt="${esc(cp.label)}"><div class="media-caption">${esc(cp.label)}<br>${previewIndex>session.position?'아직 적용 전인 장면 미리보기':'기록된 관찰 구간'} / ${modeText()}</div></div><div class="checkpoint-list">${scenario.checkpoints.map((p,i)=>`<button data-preview="${i}" class="${i===previewIndex?'selected ':''}${i<=session.position?'done':''}">${fmt(p.time)} ${esc(p.label)}</button>`).join('')}</div><div class="progress-track"><div style="width:${(session.position+1)/scenario.checkpoints.length*100}%"></div></div><div class="actions"><button id="advance" class="primary" ${session.position>=scenario.checkpoints.length-1?'disabled':''}>${session.position<0?'첫 관찰 실행':'다음 관찰 실행'}</button><span class="hint">${session.position+1} / ${scenario.checkpoints.length} 관찰 지점 재생</span></div><p class="hint">${recorded()?'버튼을 누르면 해당 구간의 저장된 실제 모델 응답을 적용합니다. GPU나 외부 API를 호출하지 않습니다.':'다음 관찰 버튼이 교육 이벤트를 처리합니다.'} 사진을 클릭하면 원본을 확대합니다.</p>${(cp.video||scenario.media?.browserPlayable)?`<details><summary>원본 영상 보기 · 탐색은 관찰 기록과 독립</summary><video controls preload="metadata" src="${esc(cp.video||scenario.media.path)}" style="width:100%" aria-label="원본 영상"></video></details>`:`<div class="notice">이 자료는 프레임으로 진행합니다. ${scenario.media?.path?`<a href="${esc(scenario.media.path)}" target="_blank">원본 파일 열기</a>`:''} ${esc(scenario.media?.codec||'')} 원본의 브라우저 호환성은 별도 확인이 필요합니다.</div>`}${modelInspector(cp)}</section><div class="stack"><section class="panel"><h2>예정 작업 목록</h2>${scenario.tasks.map((t,i)=>`<div class="task ${scenario.checkpoints[session.position]?.taskId===t.id?'active':''}"><span class="task-index">${i+1}</span>${esc(t.label)}</div>`).join('')}<p class="hint">위 순서와 강조 표시는 교재의 예정 작업입니다. 진행률은 관찰 재생 지점 수이며 작업 완료율이 아닙니다.</p>${recorded()?`<div class="notice"><strong>모델이 관찰한 작업</strong><br>${esc(observed?.observedTaskId?(scenario.tasks.find(t=>t.id===observed.observedTaskId)?.label||observed.observedTaskId):'아직 확인되지 않음')}<br>관찰 단계: ${esc({preparation:'준비',in_progress:'진행 중',completed:'완료로 관찰',unclear:'불명확'}[observed?.phase]||'미관찰')}<br><span class="hint">${esc(observed?.summaryKo||'관찰 실행 후 표시됩니다.')}</span></div>`:''}</section><section class="panel"><h2>확인 요청</h2><div id="questions"></div></section></div></div><section class="panel" style="margin-top:22px"><h2>현재 검사 기록</h2>${assessmentTable()}</section>`;
  main.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{previewIndex=Number(b.dataset.preview);render();});$('#scene-image').onclick=()=>{const d=$('#image-modal');d.querySelector('img').src=cp.image;d.showModal();};$('#advance').onclick=()=>safe(async()=>{session=Core.advance(session,scenario);previewIndex=session.position;bundle=session.bundle;await syncDb();await save();render();});$('#to-review').onclick=()=>navigate('review');renderQuestions();
}
function demoRunView(){
  const cp=currentCheckpoint(),current=scenario.checkpoints[session.position],summary=getSummary();
  const done=session.position>=scenario.checkpoints.length-1;
  const open=session.questions.filter(q=>!['resolved','stale','superseded','cancelled'].includes(q.state));
  const stage=current?.label||'준비된 작업부터 시작해 보세요';
  main.innerHTML=heading('STEP 03 · 작업 관찰','조립 진행을 함께 확인해요','다음 장면을 확인하고 필요한 질문에 답해 보세요. 답변은 검사 기록에 남습니다.',`<button id="to-review" class="secondary">전체 결과 보기</button>`)+`<div class="live-status"><div><span class="status-dot"></span><span>현재 실습 단계</span><strong>${esc(stage)}</strong></div><span class="tag">강의용 예시</span></div><div class="demo-run-grid"><section class="panel scene-panel"><div class="section-row" style="margin-top:0"><h2>작업 장면</h2><span class="tag">원본 ${fmt(cp.sourceTime??cp.time)}</span></div><div class="media-stage"><img id="scene-image" src="${esc(cp.image)}" alt="${esc(cp.label)}"><div class="media-caption"><strong>${esc(cp.label)}</strong><span>${previewIndex>session.position?'아직 기록 전 · 장면 미리보기':'실습에서 확인한 장면'}</span></div></div><div class="checkpoint-list">${scenario.checkpoints.map((p,i)=>`<button data-preview="${i}" class="${i===previewIndex?'selected ':''}${i<=session.position?'done':''}"><span>${i+1}</span> ${esc(p.label)}</button>`).join('')}</div><div class="progress-track"><div style="width:${(session.position+1)/scenario.checkpoints.length*100}%"></div></div><div class="actions"><button id="advance" class="primary" ${done?'disabled':''}>${session.position<0?'준비 장면 확인하기':done?'모든 장면 확인 완료':'다음 장면 확인하기'}</button><span class="hint">${session.position+1} / ${scenario.checkpoints.length}개 장면 확인</span></div><p class="hint">장면 순서는 실습 진행 위치입니다. 검사 완료 여부는 오른쪽 체크리스트에서 확인하세요.</p>${scenario.media?.browserPlayable?`<details><summary>원본 영상으로 보기</summary><video controls preload="none" src="${esc(scenario.media.path)}" style="width:100%" aria-label="원본 조립 영상"></video><p class="hint">영상 재생만으로 검사 기록이 바뀌지는 않습니다. 위의 장면 확인 버튼으로 실습을 진행하세요.</p></details>`:''}${modelInspector(cp)}</section><div class="stack demo-sidebar ${open.length?'has-question':''}"><section class="panel"><h2>작업 체크리스트 <span class="muted">${rows().filter(r=>r.status==='met').length} / ${rows().length}</span></h2><div class="checklist">${rows().map(({c,a,status})=>`<div class="checklist-row ${esc(status)}" data-check="${esc(c.id)}"><span class="check-symbol">${status==='met'?'✓':status==='unknown'?'?':status==='violated'?'!':'·'}</span><div><strong>${esc(c.label)}</strong><small>${status==='met'?(a?.origin==='worker_confirmed'?'작업자 확인으로 기록':'예시 관찰에서 확인'):status==='unknown'?'추가 확인이 필요합니다':status==='violated'?'조건과 다른 부분이 있습니다':status==='unassessed'&&current?.taskId===c.taskId?'진행 중 · 완료 여부는 다음 장면에서 확인':'해당 장면에서 확인 예정'}</small></div>${status==='unassessed'&&current?.taskId===c.taskId?'<span class="badge">진행 중</span>':badge(status)}</div>`).join('')}</div></section><section class="panel question-panel"><h2>작업자와 확인하기 ${open.length?`<span class="tag">${open.length}건</span>`:''}</h2><div id="questions"></div></section>${done?`<section class="completion-card ${summary.pass?'success':''}"><h2>${summary.pass?'검사가 모두 완료되었습니다':'장면 확인을 마쳤습니다'}</h2><p>${summary.pass?'확인 내용과 증거 사진으로 보고서를 만들어 보세요.':'남은 확인 사항을 검토한 뒤 현재 상태를 보고서에 기록하세요.'}</p><button id="demo-finish" class="primary">결과 확인 · 보고서 만들기</button></section>`:''}</div></div><details class="inspection-detail"><summary>항목별 상세 검사 기록</summary>${assessmentTable()}</details>`;
  main.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{previewIndex=Number(b.dataset.preview);render();});
  $('#scene-image').onclick=()=>{const d=$('#image-modal');d.querySelector('img').src=cp.image;d.showModal();};
  $('#advance').onclick=()=>safe(async()=>{session=Core.advance(session,scenario);previewIndex=session.position;bundle=session.bundle;await syncDb();await save();render();if(session.questions.some(q=>q.state==='created'))toast('화면에 보이지 않는 부분이 있습니다. 작업자 확인 요청에 답해 보세요.');});
  $('#to-review').onclick=()=>navigate('review');if($('#demo-finish'))$('#demo-finish').onclick=()=>navigate('review');renderQuestions();
}
function questionText(q){return demo()?(session.assessments[q.criterionId]?.proposedQuestion||q.text):q.text;}
function renderQuestions(){if(measurement())return measurementQuestions();
  const open=session.questions.filter(q=>!['resolved','stale','superseded','cancelled'].includes(q.state));
  $('#questions').innerHTML=open.length?open.map(q=>{const c=session.bundle.criteria.find(c=>c.id===q.criterionId),visual=policyEnabled()&&c?.kind==='visual';return `<div class="question" data-q="${esc(q.id)}"><span class="tag">${esc(qLabel[q.state]||q.state)}</span><p>${esc(questionText(q))}</p><small>대상 ${esc(demo()?(scenario.productName||'이번 조립 작업'):q.target)}<br>${visual?(policyOf(c)==='worker_attestation'?'작업자 확인을 허용한 기준입니다. 진술은 시각 증거와 별도로 표시됩니다.':'시각 증거만 인정하는 기준입니다. 답변을 남겨도 시각 증거가 생기지는 않습니다.'):(q.allowWorker?'값과 단위를 확인해 제출할 수 있습니다.':'작업자 진술만으로 시각적 확인을 완료하지 않습니다.')}</small><div class="actions"><button class="secondary deliver" data-id="${esc(q.id)}">질문 확인</button><button class="quiet speak" data-id="${esc(q.id)}">질문 듣기</button></div>${demo()&&visual?`<div class="quick-replies"><p class="hint">질문 확인 후, 직접 확인한 결과를 선택하세요.</p><button class="primary quick-reply" data-id="${esc(q.id)}" data-confirmation="met" ${q.state==='created'?'disabled':''}>방향을 확인했습니다</button><button class="danger quick-reply" data-id="${esc(q.id)}" data-confirmation="violated" ${q.state==='created'?'disabled':''}>반대로 들어가 있습니다</button></div><details><summary>자세한 확인 내용 직접 입력</summary>`:''}<form class="answer-form" data-id="${esc(q.id)}"><label class="field">확인한 대상<input name="target" value="${esc(q.target)}" required></label>${visual?`<label class="field">작업자가 직접 확인한 결과<select name="confirmation" required><option value="unknown">아직 확인할 수 없음</option><option value="met">해당 조건을 확인함</option><option value="violated">해당 조건과 다름을 확인함</option></select></label>`:q.allowWorker?`<div class="field-row"><label class="field">측정값<input name="value" inputmode="decimal" placeholder="예: 26.30" required></label><label class="field">단위<input name="unit" placeholder="mm" required></label></div>`:''}<label class="field">확인 내용<input name="text" placeholder="무엇을 어떻게 확인했는지 입력하세요" ${visual||!q.allowWorker?'required':''}></label><button class="primary" type="submit" ${q.state==='created'?'disabled':''}>답변 기록</button></form>${demo()&&visual?'</details>':''}</div>`;}).join(''):`<div class="empty">${demo()&&session.questions.some(q=>q.state==='resolved')?'작업자 답변이 기록되었습니다.<br>검사 결과에서 내용을 확인할 수 있습니다.':'현재 확인 요청이 없습니다.<br>다음 장면을 계속 확인해 주세요.'}</div>`;
  $('#questions').querySelectorAll('.quick-reply').forEach(b=>b.onclick=()=>safe(async()=>{const q=session.questions.find(q=>q.id===b.dataset.id);session=Core.answerQuestion(session,q.id,{target:q.target,confirmation:b.dataset.confirmation,text:b.dataset.confirmation==='met'?'배터리의 +/− 방향을 직접 확인했습니다.':'배터리가 표시된 +/− 방향과 반대로 들어가 있습니다.'});await syncDb();await save();render();toast('작업자 답변을 기록하고 검사 결과를 갱신했습니다.');}));
  $('#questions').querySelectorAll('.deliver').forEach(b=>b.onclick=()=>safe(async()=>{session=Core.markDelivered(session,b.dataset.id,'screen');await syncDb();await save();render();}));
  $('#questions').querySelectorAll('.speak').forEach(b=>b.onclick=()=>{if(!('speechSynthesis'in window))return toast('음성을 지원하지 않습니다. 질문 확인 버튼으로 진행하세요.');const q=session.questions.find(q=>q.id===b.dataset.id);const u=new SpeechSynthesisUtterance(questionText(q));u.lang='ko-KR';u.onend=()=>safe(async()=>{session=Core.markDelivered(session,q.id,'audio');await syncDb();await save();render();});u.onerror=()=>toast('음성을 재생하지 못했습니다. 질문 확인 버튼을 사용하세요.');speechSynthesis.cancel();speechSynthesis.speak(u);});
  $('#questions').querySelectorAll('form').forEach(f=>f.onsubmit=e=>{e.preventDefault();safe(async()=>{const data=Object.fromEntries(new FormData(f));session=Core.answerQuestion(session,f.dataset.id,data);await syncDb();await save();render();toast(demo()?'작업자 답변을 기록하고 검사 결과를 갱신했습니다.':'답변을 기록했습니다. 원래 관찰은 보존하고 현재 정책에 따라 판정했습니다.');});});
}
function reviewView(){
  if(measurement())return measurementReviewView();
  const ranges=session.bundle.criteria.filter(c=>c.kind==='range');
  const policies=policyEnabled()?session.bundle.criteria.filter(c=>c.kind==='visual'&&(!mechanical()||scenario.criteria.find(original=>original.id===c.id)?.allowWorker)):[];
  main.innerHTML=heading('STEP 04 · REVIEW','결과와 남은 확인 사항',demo()?'장면에서 확인한 내용과 작업자 답변을 검토하고 보고서로 남겨 보세요.':'모델 관찰, 작업자 진술과 현재 기준에 따른 판정을 나누어 검토합니다.')+stats()+`<section class="panel">${assessmentTable()}<div class="notice ${getSummary().pass?'success':'warning'}">${getSummary().pass?'이 실습에서 정의한 항목이 모두 충족되었습니다. 실제 제품 품질 인증은 아닙니다.':'남은 미확인·미검토·불일치 항목이 있습니다. 검토 필요 상태로 보고서를 저장할 수 있습니다.'}</div><div class="actions"><button id="go-report" class="primary">보고서 만들기</button><button id="back-run" class="secondary">관찰 / 질문으로</button></div></section><div class="grid2" style="margin-top:22px"><section class="panel"><h2>${mechanical()?'선택 · 확인 근거 비교':'기준을 바꾸어 비교'}</h2><p class="hint">${demo()?(mechanical()?'필요할 때만 비교해 보세요. 연결 핀을 직접 확인한 답변은 보존하고, 시각 증거만 인정하도록 바꾸면 확인 필요로 돌아갑니다.':'예시 관찰과 작업자 답변은 그대로 두고, 어떤 증거를 인정할지 바꿔 보세요. 배터리 항목에서 시각 증거만 인정하면 다시 확인 필요로 바뀝니다.'):recorded()?'저장된 모델 관찰은 고정합니다. 교육용 증거 인정 정책만 변경하고, 같은 관찰·작업자 답변으로 판정과 보고서를 다시 계산합니다. 항목의 의미·대상·예정 작업은 바꾸지 않습니다.':'모델에 보내지 않은 교육용 범위만 변경합니다. 원래 판독과 이전 기록은 보존합니다.'}</p>${ranges.map(c=>`<form class="range-form" data-id="${esc(c.id)}"><strong>${esc(c.label)}</strong><div class="field-row"><label class="field">하한<input name="lower" value="${esc(c.lower)}" required></label><label class="field">상한<input name="upper" value="${esc(c.upper)}" required></label><button class="secondary" type="submit">새 기준 적용</button></div></form>`).join('')}${policies.map(c=>`<form class="policy-form" data-id="${esc(c.id)}"><strong>${esc(c.label)}</strong><label class="field">이 항목의 증거 인정 기준<select name="policy"><option value="visual_only" ${policyOf(c)==='visual_only'?'selected':''}>시각 증거만 인정</option><option value="worker_attestation" ${policyOf(c)==='worker_attestation'?'selected':''}>작업자 직접 확인도 인정</option></select></label><button class="secondary" type="submit">기준 적용 · 재판정</button>${demo()&&session.assessments[c.id]?.workerConfirmation?`<button class="quiet reopen-answer" type="button" data-id="${esc(c.id)}">답변 다시 확인하기</button>`:''}</form>`).join('')}${!ranges.length&&!policies.length?'<div class="empty">이 팩은 시각적 확인 실습입니다.<br>수치 범위 변경은 계측 실습에서 제공합니다.</div>':''}${policies.length?'<div class="notice warning">작업자 확인을 인정해도 사진에서 보이지 않던 내용이 보이는 것으로 바뀌지는 않습니다. 보고서에는 작업자 확인임을 구분해 남깁니다.</div>':''}</section><section class="panel"><h2>실행 기록</h2><div>${session.events.slice(-12).map(e=>`<div class="event"><span class="event-time">${fmt(e.time??session.time)}</span>${esc(demo()?({checkpoint:'장면 확인',deliver:'질문 전달',answer:'작업자 답변',policy:'증거 인정 기준 변경',reopen:'작업자 답변 재확인',question_delivered:'질문 전달',worker_answer:'작업자 답변',policy_change:'증거 인정 기준 변경',worker_policy_changed:'확인 기준 변경',question_reopened:'답변 다시 확인'}[e.type||e.kind]||'실습 기록'):e.type||e.kind||'event')}<small class="hint"> ${esc(e.questionId||e.criterionId||e.checkpointId||'')}</small></div>`).join('')||'<p class="hint">아직 실행 기록이 없습니다.</p>'}</div><details><summary>실행 JSON 확인</summary><pre>${esc(JSON.stringify(session,null,2))}</pre></details></section></div>`;
  $('#go-report').onclick=()=>navigate('report');$('#back-run').onclick=()=>navigate('run');
  main.querySelectorAll('.reopen-answer').forEach(b=>b.onclick=()=>safe(async()=>{session=Core.reopenQuestion(session,b.dataset.id);if(measurement())previewIndex=inspectionInfo().features.findIndex(f=>f.criterionId===b.dataset.id);if(mechanical())mechanicalFlow.focusCriterion(b.dataset.id);await syncDb();await save();navigate('run');}));
  main.querySelectorAll('.range-form').forEach(f=>f.onsubmit=e=>{e.preventDefault();safe(async()=>{const v=Object.fromEntries(new FormData(f));session=Core.setRange(session,f.dataset.id,v.lower,v.upper);bundle=session.bundle;await syncDb();await save();render();toast('새 기준 버전으로 규칙을 다시 평가했습니다.');});});
  main.querySelectorAll('.policy-form').forEach(f=>f.onsubmit=e=>{e.preventDefault();safe(async()=>{const v=Object.fromEntries(new FormData(f));session=Core.setWorkerPolicy(session,f.dataset.id,v.policy);bundle=session.bundle;await syncDb();await save();render();toast('원래 관찰·답변을 보존하고 새 증거 기준으로 재판정했습니다.');});});
}
function presentationReport(inspection=false){return demo()&&(measurement()||mechanical())?formalInspectionDocument({scenario,session,summary:getSummary(),inspection}):Core.makeReport(session,scenario,demo()?{inspection}:{});}
function reportView(){main.innerHTML=heading('STEP 05 · EXPORT','기록을 보고서로 남기기','같은 실행 기록에서 보고서와 검수조서를 만듭니다. 확인되지 않은 내용은 보고서에도 그대로 남습니다.')+`<section class="panel"><div class="actions" style="margin-top:0"><button id="report-html" class="primary">${measurement()?'도면 포함 HTML 저장':'사진 포함 HTML 저장'}</button><button id="inspection-html" class="secondary">검수조서 저장</button><button id="print-report" class="secondary">인쇄 / PDF 저장</button><button id="export-csv" class="quiet">검사 CSV</button><button id="export-json" class="quiet">실행 JSON</button>${recorded()?'<button id="export-audit" class="quiet">판정 변경 이력</button>':''}<button id="export-db" class="quiet">SQLite DB</button></div><p class="hint">${measurement()?'HTML은 도면과 계측 장면을 내장해 단독으로 열 수 있습니다.':'HTML은 증거 사진을 내장해 단독으로 열 수 있습니다.'}  PDF는 브라우저 인쇄의 ‘PDF로 저장’을 이용합니다. 관찰 기록과 작업자 확인 이력을 함께 보관합니다.</p><iframe id="report-preview" class="report-frame" title="실습 보고서 미리보기" sandbox="allow-same-origin allow-modals"></iframe></section><details class="panel" style="margin-top:22px"><summary>자료 출처</summary><p class="hint">${esc(scenario.sourceNote||'원본 자료와 교육용 해석을 구분합니다.')}</p><div class="source-links">${(scenario.sources||[]).map(s=>`${s.url?`<a href="${esc(s.url)}" rel="noopener" target="_blank">${esc(s.label)}</a>`:`<span>${esc(s.label)}</span>`} <span>${esc(s.license)}</span><br>`).join('')}</div></details>`;$('#report-preview').srcdoc=presentationReport().replace(/<button[^>]*>인쇄 \/ PDF 저장<\/button>/,'').replace('<head>',`<head><base href="${esc(document.baseURI)}"><style>${fontCss}</style>`);$('#report-html').onclick=()=>safe(()=>exportReport(false));$('#inspection-html').onclick=()=>safe(()=>exportReport(true));$('#print-report').onclick=()=>$('#report-preview').contentWindow.print();$('#export-csv').onclick=exportCsv;$('#export-json').onclick=backup;if($('#export-audit'))$('#export-audit').onclick=exportAudit;$('#export-db').onclick=()=>safe(exportDb);}
async function embeddedImage(path){const r=await fetch(path);if(!r.ok)throw new Error(`증거 사진을 가져오지 못했습니다: ${path}`);const b=await r.blob();return new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(b);});}
async function exportReport(inspection){toast('증거 사진을 보고서에 포함하고 있습니다.');let html=presentationReport(inspection);if(inspection&&!demo()){html=`<!doctype html><html lang="ko"><head><meta charset="utf-8"><title>교육용 검수조서</title><style>body{font-family:Arial,sans-serif;color:#15243c;padding:36px;line-height:1.7}table{border-collapse:collapse;width:100%}td,th{padding:12px;border:1px solid #ddd}small{display:block}.badge{font-weight:bold}img{max-width:420px}</style></head><body><h1>교육용 검수조서</h1><p>${esc(scenario.title)} · ${esc(session.id)}<br>기준 ${esc(session.bundle.version)} · ${modeText()} / 작업자 입력</p>${assessmentTable()}<h2>검사 증거</h2>${rows().filter(x=>x.a?.image).map(({c,a})=>{const imgs=a.evidenceFrames?.length?a.evidenceFrames:[{path:a.image,time:a.sourceTime??a.time}];return imgs.map(im=>`<figure><img src="${esc(im.path)}" alt="${esc(c.label)}"><figcaption>${esc(c.label)} · 원본 ${fmt(im.time)} · ${esc(originLabel[a.origin]||a.origin)} · ${a.evidenceKind==='context_only'?'참고 장면 · 모델 인용 증거 없음':'인용 증거'}</figcaption></figure>`).join('');}).join('')}<p>최종 상태: ${getSummary().pass?'교육 기준 충족':'검토 필요'}</p>${recorded()?`<h2>관찰·답변·기준 변경 이력</h2><pre style="white-space:pre-wrap;word-break:break-word">${esc(JSON.stringify({model:recordingPack.model,packId:recordingPack.id,events:session.events,assessments:session.assessments},null,2))}</pre>`:""}<p>확인자: ____________________　확인일: ____________________</p><p>실제 제품 인증이나 모델 성능평가가 아닙니다.</p></body></html>`;}const fontData=await embeddedImage('assets/fonts/NotoSansKR.woff2');const license=await getText('assets/fonts/OFL.txt');html=html.replace('</head>',`<style>${fontCss.replace('assets/fonts/NotoSansKR.woff2',fontData)}</style></head>`).replace('</body>',`<details><summary>글꼴 라이선스 · Noto Sans KR</summary><pre>${esc(license)}</pre></details></body>`);const doc=new DOMParser().parseFromString(html,'text/html');for(const img of doc.querySelectorAll('img')){const src=img.getAttribute('src');if(src&&!src.startsWith('data:'))img.src=await embeddedImage(src);}for(const link of doc.querySelectorAll('a')){if((link.getAttribute('href')||'').startsWith('data/source_pack/'))link.replaceWith(doc.createTextNode(link.textContent));}download(`${scenario.id}-${inspection?'inspection':'report'}.html`,'<!doctype html>\n'+doc.documentElement.outerHTML,'text/html;charset=utf-8');toast('보고서를 저장했습니다.');}
function exportAudit(){
  if(!recorded())return;
  const audit={schema:'seminar.decision-audit.v1',scenarioId:scenario.id,sessionId:session.id,mode:'recorded',packId:recordingPack.id,model:recordingPack.model,packSha256:recordingVerification.packSha256,sourceRuleVersion:session.initialBundle.version,currentRuleVersion:session.bundle.version,inferenceDuringReplay:false,rows:rows().map(({c,a,status})=>({criterionId:c.id,target:c.target,policy:policyOf(c),modelObservation:a?.rawProposal??null,modelVerdict:a?.modelVerdict??'unassessed',workerConfirmation:a?.workerConfirmation??null,currentVerdict:status,currentOrigin:a?.origin??null,history:a?.history??[]})),events:session.events};
  download(`${scenario.id}-decision-audit.json`,JSON.stringify(audit,null,2));
}
function exportCsv(){if(measurement())return exportMeasurementCsv();const quote=v=>{let s=String(v??'');if(/^[=+@\-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const result=[['criterion_id','항목','대상','판정','값','단위','근거','출처',demo()?'예시관찰':'모델원시관찰','증거정책','응답ID'],...rows().map(({c,a,status})=>[c.id,c.label,c.target,status,a?.measurement?.valid?a.measurement.value:'',a?.measurement?.valid?a.measurement.unit:'',a?.reason??'',a?.origin??'',a?.rawProposal?.observation??a?.rawExampleVerdict??'',c.kind==='visual'&&policyEnabled()?policyOf(c):'',a?.receipt?.id??''])];download(`${scenario.id}-inspection.csv`,'\uFEFF'+result.map(r=>r.map(quote).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function exportMeasurementCsv(){const i=inspectionInfo(),summary=getSummary(),q=v=>{let s=String(v??'');if(/^[=+@\-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const data=[['product_id','drawing_id','drawing_revision','specimen_id','feature','항목','도면 하한','도면 상한','적용 하한','적용 상한','기준 변경','기록값','단위','최초후보','수치 판정','현재 상태','확인 상태','검사 완료','출처','검사자','LOT'],...rows().map(({c,a,status})=>{const f=featureFor(c.id),pending=measurementPending(c.id);return [i.productId,i.drawingId,i.drawingRevision,i.specimenId,f.code,c.label,f.lower,f.upper,c.lower,c.upper,String(c.lower)!==String(f.lower)||String(c.upper)!==String(f.upper)?'변경됨':'도면 기준',a?.measurement?.valid?a.measurement.value:'',c.unit,a?.measurement?.raw??'',a?.verdict??'unassessed',status,pending?'확인 대기':a?.measurement?.workerConfirmed?'작업자 확인 완료':a?'예시값 기록':'기록 전',summary.pass?'완료':'미완료',a?.origin??'',session.inspectionDetails?.inspector??'',session.inspectionDetails?.lot??''];})];download(`${scenario.id}-inspection.csv`,'\uFEFF'+data.map(r=>r.map(q).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
async function loadSQL(){if(SQL)return SQL;await new Promise((resolve,reject)=>{if(window.initSqlJs)return resolve();const s=document.createElement('script');s.src='vendor/sqljs/sql-wasm.js';s.onload=resolve;s.onerror=()=>reject(new Error('SQLite 라이브러리를 불러오지 못했습니다.'));document.head.appendChild(s);});SQL=await window.initSqlJs({locateFile:f=>new URL(`vendor/sqljs/${f}`,document.baseURI).href});return SQL;}
async function syncDb(){if(!bundle)return;await loadSQL();database?.close();database=new SQL.Database();database.run('CREATE TABLE company(company_id TEXT,process_id TEXT,version TEXT); CREATE TABLE tasks(id TEXT PRIMARY KEY,label TEXT); CREATE TABLE criteria(id TEXT PRIMARY KEY,task_id TEXT,label TEXT,target TEXT,kind TEXT,unit TEXT,lower_bound TEXT,upper_bound TEXT,allow_worker INTEGER); CREATE TABLE events(sequence INTEGER PRIMARY KEY,payload TEXT); CREATE TABLE assessments(criterion_id TEXT PRIMARY KEY,payload TEXT);');const b=session?.bundle||bundle;database.run('INSERT INTO company VALUES (?,?,?)',[b.companyId,b.processId,b.version]);for(const t of b.tasks)database.run('INSERT INTO tasks VALUES (?,?)',[t.id,t.label]);for(const c of b.criteria)database.run('INSERT INTO criteria VALUES (?,?,?,?,?,?,?,?,?)',[c.id,c.taskId,c.label,c.target,c.kind,c.unit||'',String(c.lower??''),String(c.upper??''),c.allowWorker?1:0]);if(measurement()){database.run('CREATE TABLE inspection(product_id TEXT,drawing_id TEXT,drawing_revision TEXT,specimen_id TEXT,payload TEXT); CREATE TABLE features(criterion_id TEXT PRIMARY KEY,code TEXT,label TEXT,instrument TEXT,payload TEXT);');const i=b.inspection||scenario.inspection;database.run('INSERT INTO inspection VALUES (?,?,?,?,?)',[i.productId,i.drawingId,i.drawingRevision,i.specimenId,JSON.stringify(i)]);for(const f of i.features)database.run('INSERT INTO features VALUES (?,?,?,?,?)',[f.criterionId,f.code,f.label,f.instrument,JSON.stringify(f)]);}if(session){session.events.forEach((e,i)=>database.run('INSERT INTO events VALUES (?,?)',[i,JSON.stringify(e)]));for(const [id,a]of Object.entries(session.assessments))database.run('INSERT INTO assessments VALUES (?,?)',[id,JSON.stringify(a)]);}}
async function exportDb(){await syncDb();download(`${scenario.id}.sqlite`,new Blob([database.export()],{type:'application/vnd.sqlite3'}));}
function backup(){if(workerEnabled()&&workerFlow.started){download('electronics-worker-session.json',JSON.stringify({format:'dynin-seminar-worker-export-v1',scenarioId:scenario.id,workerFlow:workerFlow.snapshot(),companyBuild:companyBuilder.approved?{state:companyBuilder.state,files:[]}:null},null,2));return;}if(!session)return toast('저장할 작업이 없습니다.');download(`${scenario.id}-session.json`,JSON.stringify({format:'dynin-seminar-export-v1',scenarioId:scenario.id,session,...(scenario.id==='electronics_demo'&&companyBuilder.approved?{companyBuild:{state:companyBuilder.state,files:[],note:'구축·검토 이력만 포함하며 로컬 원본 파일은 제외합니다.'}}:{})},null,2));}
async function importSession(file){
  if(documentOperation)return toast('현재 자료 처리가 끝난 뒤 진행 파일을 가져와 주세요.');
  const operation=beginDocumentOperation('import','저장된 실습 기록과 자료를 확인하고 있습니다.');
  try{
    if(file.size>10*1024*1024)throw new Error('세션 파일은 10MB 이하만 지원합니다.');const data=JSON.parse(await file.text());if(data.format==='dynin-seminar-worker-export-v1'){
      if(data.scenarioId!=='electronics_demo')throw new Error('작업자 실습의 공정이 다릅니다.');
      const prepared=await prepareScenario(scenarioIndex.find(c=>c.id===data.scenarioId),'demo');
      const imported=validateWorkerState(data.workerFlow?.state);
      const checkedBundle=Core.compileCompany(imported.bundle.sourceText,imported.bundle.sourceCsv,prepared.scenario);
      validateWorkerState(imported,checkedBundle);
      let company=null;if(data.companyBuild){company=restoreBuildState(data.companyBuild.state,prepared.scenario);if(JSON.stringify(reviewedBundle(company))!==JSON.stringify(checkedBundle))throw new Error('자료 구축 기록과 작업자 기준이 다릅니다.');}
      if(!operationCurrent(operation))return;adoptPrepared(prepared);bundle=checkedBundle;session=null;pdfText=bundle.sourceText;csvText=bundle.sourceCsv;if(company)companyBuilder.restore({state:company,files:[]},scenario);workerFlow.restore({state:imported},bundle);page=imported.started?'review':'setup';await save();render();toast('작업자 기록과 단계별 검수 결과를 복구했습니다.');return;
    }if(data.format!=='dynin-seminar-export-v1')throw new Error('지원하지 않는 진행 파일입니다.');
    const card=scenarioIndex.find(c=>c.id===data.scenarioId);if(!card)throw new Error('이 배포본에 없는 시나리오입니다.');
    const prepared=await prepareScenario(card,data.session?.mode||'fixture');Core.validateSession(data.session,prepared.scenario);
    let restoredCompany=null;if(data.companyBuild){const state=restoreBuildState(data.companyBuild.state,prepared.scenario);if(JSON.stringify(reviewedBundle(state))!==JSON.stringify(data.session.initialBundle))throw new Error('자료 구축 이력과 작업 시작 기준이 다릅니다.');restoredCompany={state,files:[]};}
    await loadSQL();if(!operationCurrent(operation))return;adoptPrepared(prepared);if(restoredCompany)companyBuilder.restore(restoredCompany,scenario);
    session=data.session;bundle=session.bundle;previewIndex=Math.max(0,session.position);pdfText=session.initialBundle?.sourceText||'가져온 세션의 컴파일 기록에 연결된 자료입니다.';csvText=session.initialBundle?.sourceCsv||'';await syncDb();page='review';await save();render();toast('저장된 기록을 확인하고 실습을 복구했습니다.');
  }finally{finishDocumentOperation(operation);}
}
function showVideoFallback(video){
  if(!video.isConnected||video.parentElement.querySelector('.video-fallback'))return;
  const note=document.createElement('div');note.className='notice warning video-fallback';note.setAttribute('role','status');
  note.innerHTML='이 브라우저에서는 원본 영상을 재생할 수 없습니다. 위의 장면 사진과 확인 버튼으로 같은 실습을 계속할 수 있습니다. <a target="_blank" rel="noopener" href="'+esc(video.getAttribute('src'))+'">원본 영상 열기</a>';
  video.after(note);
}
function render(){document.body.classList.remove('operator-active');workerFlow.leave();mechanicalFlow.leave();documentLibrary.leave();nav();if(page==='library'){void documentLibrary.render();updateDocumentLoading();return;}if(workerEnabled()&&bundle&&['setup','run','review','report'].includes(page)){workerFlow.render(page);appendLibraryAccess();updateDocumentLoading();return;}if(mechanical()&&page==='run'){mechanicalFlow.render();updateDocumentLoading();return;}if(page==='home')renderHome();else if(page==='documents')docsView();else if(page==='setup')setupView();else if(page==='run')runView();else if(page==='review')reviewView();else reportView();appendLibraryAccess();main.querySelectorAll('video').forEach(v=>{v.addEventListener('error',()=>showVideoFallback(v),{once:true});if(v.error)showVideoFallback(v);});updateDocumentLoading();}
async function safe(fn){try{await fn();}catch(e){console.error(e);toast(e.message||'처리 중 오류가 발생했습니다.');}}
$('#backup').onclick=backup;$('#import-session').onchange=e=>{if(e.target.files[0])safe(()=>importSession(e.target.files[0]));e.target.value='';};$('#close-image').onclick=()=>$('#image-modal').close();
async function boot(){
  const index=await getJSON('scenarios/index.json');catalog=Array.isArray(index)?index:index.scenarios;scenarioIndex=[...catalog];for(let i=0;i<scenarioIndex.length;i++){const config=await getJSON(scenarioIndex[i].config);for(const variant of config.variants||[])if(!scenarioIndex.some(c=>c.id===variant.id))scenarioIndex.push(variant);}
  try{storage=await openStorage();const saved=await restore();if(saved?.scenarioId){const card=scenarioIndex.find(c=>c.id===saved.scenarioId);if(card){
    const prepared=await prepareScenario(card,saved.session?.mode||saved.selectedMode||'fixture');if(saved.session)Core.validateSession(saved.session,prepared.scenario);adoptPrepared(prepared);
    session=saved.session;bundle=session?.bundle||(saved.bundle?Core.compileCompany(saved.pdfText,saved.csvText,scenario):null);pdfText=saved.pdfText||'';csvText=saved.csvText||'';previewIndex=Math.max(0,session?.position||0);page=saved.page||'documents';if(saved.presentation){measurementView=saved.presentation.measurementView==='monitor'?'monitor':'operator';previewIndex=Math.max(0,Math.min(saved.presentation.previewIndex||0,Math.max(0,(session?.position??-1)+1)));}
    if(scenario.id==='electronics_demo'&&saved.workerFlow){workerFlow.restore(saved.workerFlow,bundle);}
    if(scenario.id==='electronics_demo'&&saved.companyBuild){companyBuilder.restore(saved.companyBuild,scenario);if(!session&&!workerFlow.started&&!companyBuilder.approved){bundle=null;if(!['home','library'].includes(page))page='documents';}await save();}

  }}if(saved?.page==='library')page='library';}catch(e){console.warn('진행 복구 실패',e);session=null;bundle=null;workerFlow.reset();companyBuilder.reset();page='home';toast('저장 상태를 복구하지 못했습니다. '+e.message);}render();
}
boot().catch(e=>{main.innerHTML=`<div class="panel"><h1>실습을 시작하지 못했습니다.</h1><p class="error-text">${esc(e.message)}</p><p>로컬 서버로 접속했는지, 자료 준비와 vendor 다운로드를 완료했는지 확인해 주세요.</p><a href="README.ko.md">시작 안내</a></div>`;console.error(e);});
